vector<vector<double>> graph{{0, 4, 1}, {INF, 0, INF}, {INF, 2, 0}};
vector<double> dist{0, INF, INF};
vector<bool> used(3, false);
for (int step = 0; step < 3; ++step) {
  int u = -1;
  for (int v = 0; v < 3; ++v) if (!used[v] && (u == -1 || dist[v] < dist[u])) u = v;
  if (u == -1 || dist[u] == INF) break;
  used[u] = true;
  for (int v = 0; v < 3; ++v) dist[v] = min(dist[v], dist[u] + graph[u][v]);
}
cout << dist[1] << "\n";

